const fs = require('fs')
const path = require('path')

// entries come from a remote directory listing (sftp readdir)
function download(base, entries, read) {
  for (const e of entries) {
    const dest = path.resolve(base, e.name)
    fs.writeFileSync(dest, read(e.name))
  }
}

const { exec } = require('child_process')
const path = require('path')

function folderSize(base, name) {
  const p = path.resolve(base, name)
  exec(`du -sh '${p}'`, (e, out) => console.log(out))
}

import * as fs from 'fs'
import * as path from 'path'

class Downloader {
  constructor(private base: string) {}
  create(rel: string, data: Buffer) {
    const full = path.join(this.base, rel)
    fs.mkdirSync(path.dirname(full), { recursive: true })
    fs.writeFileSync(full, data)
  }
}

type El = { tagName: string; text: string; contentDesc: string }

export function render(elements: El[]): string {
  return `<html><body>${elements
    .map((e) => `<div><h3>${e.tagName}</h3><p>${e.text}</p><p>${e.contentDesc}</p></div>`)
    .join('')}</body></html>`
}

const { spawnSync } = require('child_process')

function search(dir, pattern) {
  const args = ['--json', '--line-number', pattern, dir]
  return spawnSync('rg', args, { encoding: 'utf-8' })
}

function prepare(html: string): string {
  const doc = new DOMParser().parseFromString(html, 'text/html')
  doc.querySelectorAll('script, object, embed, form').forEach((el) => el.remove())
  return doc.documentElement.outerHTML // handler attributes survive
}

export function Mail({ html }: { html: string }) {
  return <iframe srcDoc={prepare(html)} />
}

import { existsSync, readFileSync } from 'fs'
import { join } from 'path'

export function getReference(root: string, name: string): string {
  const p = join(root, 'references', `${name}.md`)
  if (!existsSync(p)) throw new Error(`not found: ${name}`)
  return readFileSync(p, 'utf8')
}

type Cert = { descr: string }

function row(item: Cert): string {
  return `<div><i class="certificate-tooltip" data-tooltip="cert-${item.descr}"></i></div>`
}
